import { chartSelectors, d3, IState } from "@chart-io/core";
import type { IDatum, IEventPlotProps, INumericValue } from "@chart-io/core";

import { useSelector } from "react-redux";

import { useFocused } from "./useFocused";
import { useTooltip } from "./useTooltip";

import { useLegendItem, useRender } from "../../../../hooks";
import { IBandwidthScale } from "../../IBandwidthScale";
import { renderCanvas } from "../../renderCanvas";

export interface IScatterBaseProps extends IEventPlotProps {
    /**
     * The optional key of the field used for the relative z size. This overrides the radius
     */
    z?: string;
    /**
     * The fixed radius to use for points. This is ignored if z is provided
     */
    radius?: number;
    /**
     * This is an internally used function to allow the scatter plot to render to a virtual canvas
     */
    renderVirtualCanvas?: (update: d3.Transition<Element, unknown, any, unknown>) => void;
}

/**
 * Represents a base Scatter plot that is common across both SVG and Canvas based charts
 * @param  props       The set of React properties
 * @return             The Scatter plot component
 */
export function ScatterBase({
    x,
    y,
    z,
    canvas,
    renderVirtualCanvas,
    radius = 5,
    color,
    scaleMode = "plot",
    showInLegend = true,
    interactive = true,
    onMouseOver,
    onMouseOut,
    onClick,
    layer,
}: IScatterBaseProps) {
    const data = useSelector((s: IState) => chartSelectors.data(s));
    const width = useSelector((s: IState) => chartSelectors.dimensions.width(s));
    const height = useSelector((s: IState) => chartSelectors.dimensions.height(s));
    const xScale = useSelector((s: IState) => chartSelectors.scales.getScale(s, x, scaleMode));
    const yScale = useSelector((s: IState) => chartSelectors.scales.getScale(s, y, scaleMode));
    const zScale = useSelector((s: IState) => chartSelectors.scales.getScale(s, z, scaleMode));
    const theme = useSelector((s: IState) => chartSelectors.theme(s));
    const animationDuration = useSelector((s: IState) => chartSelectors.animationDuration(s));

    // This useEffect handles mouseOver/mouseExit through the use of the `focused` value
    const fillColor = d3.color(`${color ?? theme.series.colors[0]}`);
    const strokeColor = fillColor.darker();
    fillColor.opacity = theme.series.opacity;

    useLegendItem(y, "circle", showInLegend, fillColor, z);

    const onFocus = useFocused({ xScale, yScale });
    const onTooltip = useTooltip({ x, y });

    // This is the main render function
    useRender(() => {
        if (!layer.current) return;

        const bandwidth = (xScale as IBandwidthScale).bandwidth ? (xScale as IBandwidthScale).bandwidth() / 2 : 0;

        // D3 data join
        // prettier-ignore
        const join = d3.select(layer.current)
            .selectAll("circle")
            .data(data.filter((d) => d[y] !== null && d[y] !== undefined)) as d3.Selection<SVGCircleElement, IDatum, Element, unknown>;

        // Exit points
        // prettier-ignore
        const exit = join
            .exit()
            .transition("scatter")
            .duration(animationDuration)
            .attr("r", 0)
            .remove();

        // Enter in new points
        const enter = join
            .enter()
            .append("circle")
            .attr("class", "scatter-point")
            .attr("cx", (d) => xScale(d[x] as INumericValue) + bandwidth)
            .attr("cy", (d) => yScale(d[y] as INumericValue))
            .attr("r", 0)
            .style("stroke", () => strokeColor.toString())
            .style("fill", () => fillColor.toString())
            .style("opacity", theme.series.opacity);

        // Update new and existing points
        const update = enter // @ts-ignore
            .merge(join)
            .on("mouseover", function (event, datum) {
                if (!interactive) return;

                onMouseOver && onMouseOver(datum, this, event);
                onTooltip && onTooltip({ datum, event, fillColor });
                onFocus && onFocus({ element: this, event, datum });
            })
            .on("mouseout", function (event, datum) {
                if (!interactive) return;

                onMouseOut && onMouseOut(datum, this, event);
                onTooltip && onTooltip(null);
                onFocus && onFocus(null);
            })
            .on("click", function (event, datum) {
                if (!interactive) return;

                onClick && onClick(datum, this, event);
            })
            .transition("scatter")
            .duration(animationDuration)
            .attr("cx", (d) => xScale(d[x] as INumericValue) + bandwidth)
            .attr("cy", (d) => yScale(d[y] as INumericValue))
            .attr("r", (d) => (z ? zScale(d[z] as INumericValue) : radius))
            .style("fill", () => fillColor.toString());

        renderCanvas(canvas, renderVirtualCanvas, width, height, update, exit);
    }, [
        x,
        y,
        data,
        canvas,
        renderVirtualCanvas,
        xScale,
        yScale,
        layer,
        animationDuration,
        onMouseOver,
        onMouseOut,
        onClick,
    ]);

    return null;
}
